#!/usr/bin/env node
// PreToolUse hook: src/ui-ux-pro-max/ is the source of truth. cli/assets/{data,scripts,templates}
// and .claude/skills/ui-ux-pro-max/{data,scripts} are generated by `npm run sync:assets`
// (see CLAUDE.md "Sync Rules"), so direct edits get overwritten and fail CI.
import { readFileSync } from 'node:fs';

let input = {};
try {
  input = JSON.parse(readFileSync(0, 'utf8'));
} catch {
  process.exit(0);
}

const file = String(input.tool_input?.file_path ?? '').replace(/\\/g, '/');
const mirrored = [
  /\/cli\/assets\/(data|scripts|templates)\//,
  /\/\.claude\/skills\/ui-ux-pro-max\/(data|scripts)\//,
];

if (mirrored.some((re) => re.test(file))) {
  process.stderr.write(
    `Blocked: ${file} is a generated mirror. Edit the same path under src/ui-ux-pro-max/ ` +
      `and then run \`cd cli && npm run sync:assets\`.\n`,
  );
  process.exit(2);
}
process.exit(0);
